/**
 * Frontend data loader for The AI Native.
 *
 * Reads `data/items.json` (generated by scripts/export.py from the SQLite DB).
 * The Python pipeline is the source of truth; this is a static snapshot
 * regenerated on each pipeline run and committed to git so Vercel can build.
 */
import fs from "node:fs";
import path from "node:path";

export type Section = "Organization" | "HR" | "Industry";

// HR sub-modules per PRD §6.1. Display priority order set by the editor:
// 组织设计 > 薪酬 > 绩效 > 员工体验 > 学发 > 招聘
export type HRModule = "组织设计" | "薪酬" | "绩效" | "员工体验" | "学发" | "招聘";

export const HR_MODULE_ORDER: HRModule[] = [
  "组织设计",
  "薪酬",
  "绩效",
  "员工体验",
  "学发",
  "招聘",
];

// 10-category insight classification (PRD v2 §3)
export type InsightClass =
  | "Org Architecture"
  | "Talent Density"
  | "AI-Human Collaboration"
  | "Management Systems"
  | "Decision Design"
  | "Performance Systems"
  | "Capability Transformation"
  | "Labor Economics"
  | "Organizational Scaling"
  | "AI Governance";

export type Item = {
  id: number;
  url: string;
  title: string;
  source: string;
  source_type: string;
  section: Section | null;
  hr_module: HRModule | null;
  sub_tag: string | null;
  hook: string | null;
  // Legacy fields (v1) — kept for back-compat during migration
  summary: string | null;
  implication: string | null;
  // v2 §3 structured intelligence fields
  what_happened: string | null;
  why_matters: string | null;
  org_implication: string | null;
  talent_implication: string | null;
  hr_operating_implication: string | null;
  prediction: string | null;
  insight_class: InsightClass | null;
  author: string | null;
  published_at: string | null;
  perspective_score: number | null;
  practice_score: number | null;
  frontier_score: number | null;
  score_reasoning: string | null;
  total_score: number;
  is_featured: boolean;
};

export type Issue = {
  number: string;
  date_iso: string;
  date_label: string;
};

export type Skill = {
  id: string;
  name: string;
  vendor: string;
  category: string;
  one_line: string;
  summary: string;
  url: string;
  featured: boolean;
};

export type Payload = {
  issue: Issue;
  generated_at: string;
  min_score_threshold: number;
  item_count: number;
  featured_count: number;
  items: Item[];
  skills: Skill[];
};

function dataPath(): string {
  return path.resolve(process.cwd(), "data", "items.json");
}

// No cache: file reads are cheap; `next build` reads once per static page.
export function loadPayload(): Payload {
  const raw = fs.readFileSync(dataPath(), "utf-8");
  return JSON.parse(raw) as Payload;
}

export function getAllItems(): Item[] {
  return loadPayload().items;
}

export function getFeatured(section?: Section): Item[] {
  const items = loadPayload().items.filter((i) => i.is_featured);
  return section ? items.filter((i) => i.section === section) : items;
}

export function getBySection(section: Section): Item[] {
  return loadPayload().items.filter((i) => i.section === section);
}

export function getIssue(): Issue {
  return loadPayload().issue;
}

export function getSkills(): Skill[] {
  return loadPayload().skills;
}

export function getFeaturedSkill(): Skill | undefined {
  return loadPayload().skills.find((s) => s.featured);
}

/** Top N signals across all sections by total_score — for the homepage hero */
export function getTopSignals(n: number = 5): Item[] {
  return loadPayload().items
    .filter((i) => i.what_happened) // only items with v2 intel
    .slice(0, n);
}

export function getStats(): { items: number; featured: number; skills: number; sources: number } {
  const p = loadPayload();
  const sources = new Set(p.items.map((i) => i.source)).size;
  return {
    items: p.item_count,
    featured: p.featured_count,
    skills: p.skills.length,
    sources,
  };
}

